    choices: [
      { id: 'q2a', text: 'JavaScript' },
      { id: 'q2b', text: 'C' },
      { id: 'q2c', text: 'C++' },
      { id: 'q2d', text: 'Rust' },
    ],
    correct: ['q2b', 'q2c', 'q2d'],
  },
  {
    id: 'q3',
    text: 'Which of the following languages support first-class functions?',
    choices: [
      { id: 'q3a', text: 'JavaScript' },
      { id: 'q3b', text: 'Python' },
      { id: 'q3c', text: 'Haskell' },
      { id: 'q3d', text: 'Assembly' },
    ],
    correct: ['q3a', 'q3b', 'q3c'],
  },
];

function arraysEqual(a, b) {
  return a.length === b.length && [...a].sort().every((v, i) => v === [...b].sort()[i]);
}

function buildQuiz() {
  const form = document.getElementById('quiz-form');

  QUESTIONS.forEach((q, index) => {
    const field = document.createElement('div');
    field.className = 'form-field';
    field.id = `field-${q.id}`;

    const numberSpan = document.createElement('span');
    numberSpan.className = 'question-number';
    numberSpan.textContent = `Question ${index + 1} of ${QUESTIONS.length}`;

    const label = document.createElement('span');
    label.className = 'question-label';
    label.id = `label-${q.id}`;
    label.textContent = q.text;

    field.appendChild(numberSpan);
    field.appendChild(label);

    if (q.helpText) {
      const help = document.createElement('p');
      help.className = 'help-text';
      help.id = `help-${q.id}`;
      help.textContent = q.helpText;
      field.appendChild(help);
    }

    const group = document.createElement('div');
    group.className = 'choices';
    group.setAttribute('role', 'group');
    group.setAttribute('aria-labelledby', `label-${q.id}${q.helpText ? ` help-${q.id}` : ''}`);

    q.choices.forEach(choice => {
      const choiceLabel = document.createElement('label');
      choiceLabel.className = 'choice';
      choiceLabel.htmlFor = choice.id;

      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.id = choice.id;
      checkbox.name = q.id;
      checkbox.value = choice.id;

      checkbox.addEventListener('change', () => {
        choiceLabel.classList.toggle('selected', checkbox.checked);
      });

      const text = document.createElement('span');
      text.className = 'choice-text';
      text.textContent = choice.text;

      choiceLabel.appendChild(checkbox);
      choiceLabel.appendChild(text);
      group.appendChild(choiceLabel);
    });

    field.appendChild(group);
    form.appendChild(field);
  });

  const actions = document.createElement('div');
  actions.className = 'form-actions';

  const submitBtn = document.createElement('button');
  submitBtn.type = 'submit';
  submitBtn.className = 'btn-submit';
  submitBtn.textContent = 'Submit Answers';

  actions.appendChild(submitBtn);
  form.appendChild(actions);
}

function handleSubmit(e) {
  e.preventDefault();

  let score = 0;

  QUESTIONS.forEach(q => {
    const field = document.getElementById(`field-${q.id}`);
    const checked = [...field.querySelectorAll('input[type="checkbox"]:checked')].map(cb => cb.value);
    const isCorrect = arraysEqual(checked, q.correct);

    field.classList.remove('correct', 'incorrect');
    field.querySelector('.feedback-badge')?.remove();

    field.classList.add(isCorrect ? 'correct' : 'incorrect');

    const badge = document.createElement('span');
    badge.className = `feedback-badge ${isCorrect ? 'correct' : 'incorrect'}`;
    badge.setAttribute('aria-live', 'polite');
    badge.textContent = isCorrect ? '✓ Correct' : '✗ Incorrect';
    field.appendChild(badge);

    if (isCorrect) score++;
  });

  showResults(score);
}

function showResults(score) {
  const total = QUESTIONS.length;
  const panel = document.getElementById('results-panel');
  const scoreEl = document.getElementById('results-score');
  const verdictEl = document.getElementById('results-verdict');

  scoreEl.textContent = `${score} / ${total}`;

  const pct = score / total;
  verdictEl.textContent =
    pct === 1 ? '🎉 Perfect score! You really know your languages.' :
    pct >= 0.67 ? '👍 Great job! Just a couple to review.' :
    pct >= 0.34 ? '📖 Not bad — brush up on a few topics.' :
    '💡 Keep studying — you\'ll get there!';

  panel.classList.add('visible');
  panel.focus();
}

function resetQuiz() {
  const panel = document.getElementById('results-panel');
  panel.classList.remove('visible');

  document.querySelectorAll('.form-field').forEach(field => {
    field.classList.remove('correct', 'incorrect');
    field.querySelector('.feedback-badge')?.remove();
  });

  document.querySelectorAll('input[type="checkbox"]').forEach(cb => {
    cb.checked = false;
    cb.closest('.choice')?.classList.remove('selected');
  });
}

document.addEventListener('DOMContentLoaded', () => {
  buildQuiz();
  document.getElementById('quiz-form').addEventListener('submit', handleSubmit);
  document.getElementById('btn-retry').addEventListener('click', resetQuiz);
});
