    q.choices.forEach(choice => {
      const choiceLabel = document.createElement('label');
      choiceLabel.className = 'choice';
      choiceLabel.htmlFor = choice.id;

      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.id = choice.id;
      checkbox.name = q.id;
      checkbox.value = choice.id;

      checkbox.addEventListener('change', () => {
        choiceLabel.classList.toggle('selected', checkbox.checked);
      });

      const text = document.createElement('span');
      text.className = 'choice-text';
      text.textContent = choice.text;

      choiceLabel.appendChild(checkbox);
      choiceLabel.appendChild(text);
      group.appendChild(choiceLabel);
    });

    field.appendChild(group);
    form.appendChild(field);
  });

  const actions = document.createElement('div');
  actions.className = 'form-actions';

  const submitBtn = document.createElement('button');
  submitBtn.type = 'submit';
  submitBtn.className = 'btn-submit';
  submitBtn.textContent = 'Submit Answers';

  actions.appendChild(submitBtn);
  form.appendChild(actions);
}

function handleSubmit(e) {
  e.preventDefault();

  let score = 0;

  QUESTIONS.forEach(q => {
    const field = document.getElementById(`field-${q.id}`);
    const checked = [...field.querySelectorAll('input[type="checkbox"]:checked')].map(cb => cb.value);
    const isCorrect = arraysEqual(checked, q.correct);

    field.classList.remove('correct', 'incorrect');
    field.querySelector('.feedback-badge')?.remove();

    field.classList.add(isCorrect ? 'correct' : 'incorrect');

