function showResults(score) {
  const total = QUESTIONS.length;
  const panel = document.getElementById('results-panel');
  const scoreEl = document.getElementById('results-score');
  const verdictEl = document.getElementById('results-verdict');

  scoreEl.textContent = `${score} / ${total}`;

  const pct = score / total;
  verdictEl.textContent =
    pct === 1 ? '🎉 Perfect score! You really know your languages.' :
    pct >= 0.67 ? '👍 Great job! Just a couple to review.' :
    pct >= 0.34 ? '📖 Not bad — brush up on a few topics.' :
    '💡 Keep studying — you\'ll get there!';

  panel.classList.add('visible');
  panel.focus();
}

function resetQuiz() {
  const panel = document.getElementById('results-panel');
  panel.classList.remove('visible');

  document.querySelectorAll('.form-field').forEach(field => {
    field.classList.remove('correct', 'incorrect');
    field.querySelector('.feedback-badge')?.remove();
  });

  document.querySelectorAll('input[type="checkbox"]').forEach(cb => {
    cb.checked = false;
    cb.closest('.choice')?.classList.remove('selected');
  });
}

document.addEventListener('DOMContentLoaded', () => {
  buildQuiz();
  document.getElementById('quiz-form').addEventListener('submit', handleSubmit);
  document.getElementById('btn-retry').addEventListener('click', resetQuiz);
});

